                                          <![endif]-->\\n                              <table\\n                                align=\\"center\\"\\n                                border=\\"0\\"\\n                                cellpadding=\\"0\\"\\n                                cellspacing=\\"0\\"\\n                                width=\\"100%\\"\\n                                class=\\"tableWhite\\"\\n                              >\\n                                <tr>\\n                                  <td\\n                                    align=\\"left\\"\\n                                    valign=\\"top\\"\\n                                    style=\\"padding: 20px; padding-left: 30px; padding-bottom: 0px;\\"\\n                                  >\\n                                    <a\\n                                      href=\\"https://www.abb.com/\\"\\n                                      target=\\"_blank\\"\\n                                      style=\\"text-decoration: none;\\"\\n                                      ><img\\n                                          src=\\"data:image/png;base64,\\"\\n                                          width=\\"80\\" height=\\"80\\"\\n                                          alt=\\"ABB\\"\\n                                          style=\\"width:80px; height:80px;\\"\\n                                        />\\n                                    </a>\\n                                  </td>\\n                                </tr>\\n                                <tr>\\n                                  <td\\n                                    align=\\"left\\"\\n                                    valign=\\"top\\"\\n                                    style=\\"\\n                                      padding-right: 30px;\\n                                      padding-top: 10px;\\n                                      padding-bottom: 30px;\\n                                      padding-left: 30px;\\n                                    \\"\\n                                  >\\n                                    <p\\n                                      style=\\"\\n                                        color: #15141a;\\n                                        font-family: 'Roboto', sans-serif;\\n                                        font-size: 18px;\\n                                        font-style: normal;\\n                                        font-weight: 500;\\n                                        line-height: 18px;\\n                                        letter-spacing: normal;\\n                                        margin: 0;\\n                                        padding: 0;\\n                                        text-align: left;\\n                                      \\"\\n                                    >\\n                                      {% if locale == \\"de\\" %}Alarm ausgelöst: {% elseif locale == \\"it\\" %}Allarme attivato: {% elseif locale == \\"fr\\" %}Alarme déclenchée : {% else %}Alarm triggered: {% endif %}{{asset.name}} ({{asset.gai}}) - {{alarm.msg}}\\n                                    </p>\\n                                    <p\\n                                      style=\\"\\n                                        color: #15141a;\\n                                        font-family: 'Roboto', sans-serif;\\n                                        font-size: 18px;\\n                                        font-style: normal;\\n                                        font-weight: 500;\\n                                        line-height: 18px;\\n                                        letter-spacing: normal;\\n                                        margin: 0;\\n                                        padding: 0;\\n                                        text-align: left;\\n                                      \\"\\n                                    >\\n                                    </p>\\n                                  </td>\\n                                </tr>\\n                                <tr>\\n                                    <td\\n                                      align=\\"left\\"\\n                                      valign=\\"middle\\"\\n                                      style=\\"\\n                                        padding-right: 30px;\\n                                        padding-bottom: 20px;\\n                                        padding-left: 30px;\\n                                      \\"\\n                                    >\\n                                      <table cellspacing=\\"0\\" cellpadding=\\"0\\">\\n                                        <tr>\\n                                          <td align=\\"center\\" bgcolor=\\"#000001\\" id=\\"button\\" style=\\"border-radius: 999px;\\">\\n                                            <a href=\\"{% if alarm.gone_ts is null %}https://{{domain_name}}/suites/alert-center{% if alarm.alarm_id != 0 %}?alarm_id={{alarm.alarm_id}}{% endif %}{% else %}https://{{domain_name}}/suites/alert-center/alarms/history{% endif %}\\"\\n                                              target=\\"_blank\\"\\n                                              style=\\"\\n                                                border-radius: 999px;\\n                                                width: 200px;\\n                                                border: 1px solid #000001;\\n                                                color: #fffffe;\\n                                                display: inline-block;\\n                                                font-size: 15px;\\n                                                font-family: 'Roboto', Arial, sans-serif;\\n                                                font-weight: 500;\\n                                                letter-spacing: 0.3px;\\n                                            