html>\\n            <html>\\n              <head>\\n                  <!-- trx_0075 -->\\n                  <link\\n                    href=\\"https://fonts.googleapis.com/css?family=Roboto:400,500&display=swap\\"\\n                    rel=\\"stylesheet\\"\\n                  />\\n                  <meta http-equiv=\\"Content-Type\\" content=\\"text/html; charset=utf-8\\" />\\n                  <meta name=\\"viewport\\" content=\\"width=device-width, initial-scale=1\\" />\\n                  <meta http-equiv=\\"X-UA-Compatible\\" content=\\"IE=edge\\" />\\n                  <title>ABB BuildingPro Email</title>\\n\\n                  <style type=\\"text/css\\">\\n                    p {\\n                      margin: 10px 0;\\n                      padding: 0;\\n                    }\\n                    h1,\\n                    h2,\\n                    h3,\\n                    h4,\\n                    h5,\\n                    h6 {\\n                      display: block;\\n                      margin: 0;\\n                      padding: 0;\\n                    }\\n                    img,\\n                    a img {\\n                      border: 0;\\n                      height: auto;\\n                      outline: none;\\n                      text-decoration: none;\\n                      width: 80px;\\n                    }\\n                    body,\\n                    #bodyTable,\\n                    #bodyCell {\\n                      height: 100%;\\n                      margin: 0;\\n                      padding: 0;\\n                      width: 100%;\\n                    }\\n                    /* CLIENT-SPECIFIC STYLES */\\n                    #outlook a {\\n                      padding: 0;\\n                    } /* Force Outlook 2007 and up to provide a \\"view in browser\\" message. */\\n                    @-ms-viewport {\\n                      width: device-width;\\n                    } /* Force IE \\"snap mode\\" to render widths normally. */\\n                    img {\\n                      -ms-interpolation-mode: bicubic;\\n                    } /* Force IE to smoothly render resized images. */\\n                    table {\\n                      mso-table-lspace: 0pt;\\n                      mso-table-rspace: 0pt;\\n                    } /* Remove spacing between tables in Outlook Desktop. */\\n                    .ReadMsgBody {\\n                      width: 100%;\\n                    }\\n                    .ExternalClass {\\n                      width: 100%;\\n                    } /* Force Outlook.com to display emails at full width. */\\n                    p,\\n                    a,\\n                    li,\\n                    td,\\n                    blockquote {\\n                      mso-line-height-rule: exactly;\\n                    } /* Force Outlook Desktop to render line heights as they're originally set. */\\n                    a[href^=\\"tel\\"],\\n                    a[href^=\\"sms\\"] {\\n                      color: inherit;\\n                      cursor: default;\\n                      text-decoration: none;\\n                    } /* Force mobile devices to inherit declared link styles. */\\n                    p,\\n                    a,\\n                    li,\\n                    td,\\n                    body,\\n                    table,\\n                    blockquote {\\n                      -ms-text-size-adjust: 100%;\\n                      -webkit-text-size-adjust: 100%;\\n                    } /* Prevent Windows- and Webkit-based platforms from changing declared text sizes. */\\n                    .ExternalClass,\\n                    .ExternalClass p,\\n                    .ExternalClass td,\\n                    .ExternalClass div,\\n                    .ExternalClass span,\\n                    .ExternalClass font {\\n                      line-height: 100%;\\n                    } /* Force Outlook.com to display line heights normally. */\\n                    a[x-apple-data-detectors] {\\n                      color: inherit !important;\\n                      text-decoration: none !important;\\n                      font-size: inherit !important;\\n                      font-family: inherit !important;\\n                      font-weight: inherit !important;\\n                      line-height: inherit !important;\\n                    } /* Force iOS devices to heed link styles set in CSS. */\\n\\n                    #button a {\\n                      text-decoration: none;\\n                    } /* Necessary for Outlook on Windows Phone */\\n                    /* STYLES FOR MOBILE */\\n                    @media only screen and (max-width: 640px) {\\n                      body {\\n                        width: 100% !important;\\n                        max-width: 100% !important;\\n                      }\\n                      h1 {\\n                        font-size: 24px !important;\\n                      }\\n                      .emailContainer {\\n                        width: 91% !important;\\n                        max-width: 91% !important;\\n                      }\\n                      .footerContent {\\n                        padding-bottom: 0 !important;\\n                      }\\n                      .footerContent p {\\n                        font-size: 13px !important;\\n                        padding-bottom: 40px !important;\\n                      }\\n                      .utilityLink {\\n                        border-bottom: 1px solid #efeeea;\\n                        display: block;\\n                        font-size: 13px !important;\\n                        padding-top: 15px;\\n                        padding-bottom: 15px;\\n                      }\\n                      .mobileHide {\\n                        display: none;\\n                        visibility: hidden;\\n                      }\\n                    }\\n                  </sty